RSpec.describe Timekeeping::Handoff::Checkpoint do
  # "A value that still has no home is refused as a backstop, naming the table; it is never dropped."
  it "refuses an entries row carrying a column with no home, naming the table, instead of dropping it" do
    stamp = Time.utc(2026, 1, 1, 12, 0, 0)
    entry = {
      "id" => 10, "company_id" => 1, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
      "work_date" => Date.new(2026, 1, 1), "duration" => 1.5, "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => stamp, "updated_at" => stamp,
      "billed_amount" => 120
    }
    tables = described_class::TABLES.keys.index_with { [] }.merge("entries" => [entry])

    expect { described_class.build(tables: tables) }
      .to raise_error(described_class::ShapeError, /entries/)
  end
end

