RSpec.describe Timekeeping::Handoff::Checkpoint do
  # "Export, load, export again, and get equal counts and checksums."
  # Postgres returns rows in no fixed order, so the checksum must not depend on it.
  it "gives the same digest for the same rows returned in a different order, and keeps fields from running together" do
    stamp = Time.utc(2026, 1, 1, 12, 0, 0)
    entry = lambda do |id, note, source|
      {
        "id" => id, "company_id" => 1, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
        "work_date" => Date.new(2026, 1, 1), "duration" => 1.5, "note" => note, "bill_status" => "unbilled",
        "review_status" => "not_required", "locked" => false, "source" => source, "source_metadata" => {},
        "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => stamp, "updated_at" => stamp
      }
    end
    empty = described_class::TABLES.keys.index_with { [] }
    rows = [entry.call(1, "a", "manual"), entry.call(2, "b", "manual")]

    forward = described_class.build(tables: empty.merge("entries" => rows))
    backward = described_class.build(tables: empty.merge("entries" => rows.reverse))
    expect(backward.digest).to eq(forward.digest)

    joined_left = described_class.build(tables: empty.merge("entries" => [entry.call(1, "a|b", "c")]))
    joined_right = described_class.build(tables: empty.merge("entries" => [entry.call(1, "a", "b|c")]))
    expect(joined_left.digest).not_to eq(joined_right.digest)
  end
end

RSpec.describe Timekeeping::Handoff::Checkpoint do
  # "A changed field, or a float differing in its last bit, fails `verify` for that table and company only."
  it "verify reports only entries for company 1 when one duration is swapped for the next float in transit" do
    entry_row = lambda do |id, company_id, duration|
      {
        "id" => id, "company_id" => company_id, "version" => 2, "project_id" => 10, "user_id" => 20,
        "agent_id" => nil, "work_date" => Date.new(2026, 1, 5), "duration" => duration, "note" => "",
        "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false,
        "source" => "manual", "source_metadata" => {}, "external_run_id" => nil,
        "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {}, "discarded_at" => nil,
        "created_at" => Time.utc(2026, 1, 5, 9, 0, 0, 123_456), "updated_at" => Time.utc(2026, 1, 5, 9, 0, 0, 654_321)
      }
    end
    tables_with = lambda do |entries|
      {
        "entries" => entries, "reservations" => [], "invoice_operations" => [],
        "entry_audits" => [], "idempotency_records" => []
      }
    end
    duration = 0.1 + 0.2
    original = described_class.build(tables: tables_with.call([entry_row.call(1, 1, duration), entry_row.call(2, 2, duration)]))
    altered = described_class.build(tables: tables_with.call([entry_row.call(1, 1, duration.next_float), entry_row.call(2, 2, duration)]))

    # Carry the original digest with the altered rows, as a checkpoint changed in transit would.
    original_json = JSON.parse(original.to_json)
    altered_json = JSON.parse(altered.to_json)
    company_one_checksum = original.digest.fetch("entries").fetch(1).fetch(:checksum)
    digest_keys = original_json.keys.select { |key| JSON.generate(original_json[key]).include?(company_one_checksum) }
    expect(digest_keys).not_to be_empty
    tampered = described_class.from_json(JSON.generate(altered_json.merge(original_json.slice(*digest_keys))))

    mismatches = described_class.verify(tampered)

    expect(mismatches.map { |mismatch| [mismatch[:table], mismatch[:company_id]] }).to eq([["entries", 1]])
  end
end

RSpec.describe Timekeeping::Handoff::Checkpoint do
  # "Provide a pure `verify` that recomputes counts and checksums and reports every mismatch per table and per company."
  it "verify reports a company whose rows were all removed while its digest entry stayed" do
    entry_row = lambda do |id, company_id|
      {
        "id" => id, "company_id" => company_id, "version" => 1, "project_id" => 10, "user_id" => 20,
        "agent_id" => nil, "work_date" => Date.new(2026, 1, 5), "duration" => 60.0, "note" => "",
        "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false,
        "source" => "manual", "source_metadata" => {}, "external_run_id" => nil,
        "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {}, "discarded_at" => nil,
        "created_at" => Time.utc(2026, 1, 5, 9), "updated_at" => Time.utc(2026, 1, 5, 9)
      }
    end
    tables_with = lambda do |entries|
      {
        "entries" => entries, "reservations" => [], "invoice_operations" => [],
        "entry_audits" => [], "idempotency_records" => []
      }
    end
    both = described_class.build(tables: tables_with.call([entry_row.call(1, 1), entry_row.call(2, 2)]))
    only_one = described_class.build(tables: tables_with.call([entry_row.call(1, 1)]))

    # Company 2's rows vanish but its digest entry is kept, so a check that only
    # walks the companies present in the rows would see nothing wrong.
    both_json = JSON.parse(both.to_json)
    only_one_json = JSON.parse(only_one.to_json)
    company_two_checksum = both.digest.fetch("entries").fetch(2).fetch(:checksum)
    digest_keys = both_json.keys.select { |key| JSON.generate(both_json[key]).include?(company_two_checksum) }
    expect(digest_keys).not_to be_empty
    tampered = described_class.from_json(JSON.generate(only_one_json.merge(both_json.slice(*digest_keys))))

    mismatches = described_class.verify(tampered)

    expect(mismatches.map { |mismatch| [mismatch[:table], mismatch[:company_id]] }).to eq([["entries", 2]])
  end
end
